/** 
 * Given a BigQuery TableRow, returns a protocol-buffer message that can be used to write data using the BigQuery Storage API.
 */
public static DynamicMessage messageFromTableRow(SchemaInformation schemaInformation,Descriptor descriptor,TableRow tableRow,boolean ignoreUnkownValues) throws SchemaConversionException {
  @Nullable Object fValue=tableRow.get("f");
  if (fValue instanceof List) {
    List<AbstractMap<String,Object>> cells=(List<AbstractMap<String,Object>>)fValue;
    DynamicMessage.Builder builder=DynamicMessage.newBuilder(descriptor);
    int cellsToProcess=cells.size();
    if (cells.size() > descriptor.getFields().size()) {
      if (ignoreUnkownValues) {
        cellsToProcess=descriptor.getFields().size();
      }
      else {
        throw new SchemaTooNarrowException("TableRow contained too many fields and ignoreUnknownValues not set.");
      }
    }
    try {
      for (int i=0; i < cellsToProcess; ++i) {
        AbstractMap<String,Object> cell=cells.get(i);
        try {
          FieldDescriptor fieldDescriptor=descriptor.getFields().get(i);
          SchemaInformation fieldSchemaInformation=schemaInformation.getSchemaForField(i);
          try {
            @Nullable Object value=messageValueFromFieldValue(fieldSchemaInformation,fieldDescriptor,cell.get("v"),ignoreUnkownValues);
            if (value != null) {
              builder.setField(fieldDescriptor,value);
            }
          }
          catch (Exception e) {
            throw new SchemaDoesntMatchException("Problem converting field " + (fieldSchemaInformation != null ? fieldSchemaInformation.getFullName() : "unknown") + " expected type: "+ (fieldSchemaInformation != null ? fieldSchemaInformation.getType() : "unknown"),e);
          }
        }
        catch (IndexOutOfBoundsException e) {
          throw new SchemaDoesntMatchException("Field index out of bounds", e);
        }
      }
      try {
        return builder.build();
      }
      catch (Exception e) {
        throw new SchemaDoesntMatchException("Could convert schema for " + (schemaInformation != null ? schemaInformation.getFullName() : "unknown"),e);
      }
    }
    catch (NullPointerException e) {
      throw new SchemaDoesntMatchException("Null pointer encountered during conversion", e);
    }
    catch (RuntimeException e) {
      throw new SchemaDoesntMatchException("Unexpected runtime exception during conversion", e);
    }
  }
  else {
    return messageFromMap(schemaInformation,descriptor,tableRow,ignoreUnkownValues);
  }
}
